CREATE TABLE yshop_store_shop(id BIGINT PRIMARY KEY,name VARCHAR(100),mobile VARCHAR(20),images VARCHAR(100),address VARCHAR(100),address_map VARCHAR(100),start_time TIMESTAMP,end_time TIMESTAMP,lng VARCHAR(30),lat VARCHAR(30),status INT,admin_id VARCHAR(100),deleted INT DEFAULT 0,distance INT DEFAULT 0,min_price DECIMAL(10,2) DEFAULT 0,delivery_price DECIMAL(10,2) DEFAULT 0);
CREATE TABLE yshop_store_product_category(id BIGINT PRIMARY KEY,shop_id BIGINT,parent_id BIGINT,name VARCHAR(100),pic_url VARCHAR(256),status INT,deleted INT DEFAULT 0);
CREATE TABLE yshop_store_product(id BIGINT AUTO_INCREMENT PRIMARY KEY,shop_id BIGINT,image VARCHAR(100),slider_image VARCHAR(100),store_name VARCHAR(100),store_info VARCHAR(100),keyword VARCHAR(100),cate_id VARCHAR(64),stock INT,sales INT,is_show INT,is_integral INT,give_integral DECIMAL(10,2),deleted INT DEFAULT 0);
CREATE TABLE yshop_store_product_attr_value(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id BIGINT,sku VARCHAR(256),stock INT,sales INT,price DECIMAL(10,2),cost DECIMAL(10,2));
CREATE TABLE yshop_user(id BIGINT PRIMARY KEY,username VARCHAR(100),password VARCHAR(100),nickname VARCHAR(100),deleted INT DEFAULT 0);
CREATE TABLE yshop_user_address(id BIGINT PRIMARY KEY,uid BIGINT,real_name VARCHAR(100),phone VARCHAR(30),address VARCHAR(100),detail VARCHAR(100),deleted INT DEFAULT 0);
CREATE TABLE yshop_coupon_user(id BIGINT PRIMARY KEY,shop_id VARCHAR(100),title VARCHAR(100),least DECIMAL(10,2),`value` DECIMAL(10,2),start_time TIMESTAMP,end_time TIMESTAMP,type INT,user_id BIGINT,status INT,coupon_id BIGINT,deleted INT DEFAULT 0,reserved_order_id VARCHAR(32));
CREATE TABLE yshop_order_number(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id VARCHAR(32));
CREATE TABLE yshop_store_order(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id VARCHAR(32) UNIQUE,shop_id BIGINT,shop_name VARCHAR(100),uid BIGINT,real_name VARCHAR(100),user_phone VARCHAR(30),user_address VARCHAR(200),total_num INT,total_price DECIMAL(10,2),total_postage DECIMAL(10,2),pay_price DECIMAL(10,2),pay_postage DECIMAL(10,2),coupon_id BIGINT DEFAULT 0,coupon_price DECIMAL(10,2),paid INT DEFAULT 0,pay_type VARCHAR(32),order_type VARCHAR(50),gain_integral DECIMAL(10,2),mark VARCHAR(512),cost DECIMAL(10,2),get_time TIMESTAMP,number_id BIGINT,create_time TIMESTAMP,update_time TIMESTAMP,ordering_version INT DEFAULT 0,deleted INT DEFAULT 0,status INT DEFAULT 0,refund_status INT DEFAULT 0);
CREATE TABLE yshop_store_order_cart_info(id BIGINT AUTO_INCREMENT PRIMARY KEY,oid BIGINT,order_id VARCHAR(32),product_id BIGINT,cart_info TEXT,`unique` VARCHAR(50),is_after_sales INT,title VARCHAR(100),image VARCHAR(500),number INT,price DECIMAL(10,2),spec VARCHAR(500));
CREATE TABLE yshop_store_order_status(id BIGINT AUTO_INCREMENT PRIMARY KEY,oid BIGINT,change_type VARCHAR(32),change_message VARCHAR(256),change_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE yshop_order_submission(uid BIGINT,idempotency_key VARCHAR(64),request_hash CHAR(64),order_id VARCHAR(32),create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(uid,idempotency_key),UNIQUE(order_id));
CREATE TABLE yshop_order_inventory_reservation(order_id VARCHAR(32),line_no INT,product_id BIGINT,sku_id BIGINT,quantity INT CHECK(quantity>0),released_at TIMESTAMP,PRIMARY KEY(order_id,line_no));
